#include "harness.hpp"
#include "inittrack.hpp"

using namespace inittrack;

int main() {
    h_init();
    Tracker t;
    t.add("Mira", 17, 3);
    t.add("Orc", 12, 1);
    t.add("Brann", 17, 4);
    CHECK_EQ(t.order(), (std::vector<std::string>{"Brann", "Mira", "Orc"}));
    auto ev = t.next_turn();
    CHECK_EQ(ev.size(), 2u);
    CHECK_EQ(t.round(), 1);
    CHECK_EQ(*t.current(), std::string("Brann"));
    return h_report();
}

