    int at = find(who);
    if (at < 0 || turns < 1) throw std::invalid_argument("bad status request");
    auto &sts = list_[static_cast<size_t>(at)].statuses;
    for (auto &s : sts) {
        if (s.first == status) {
            if (turns > s.second) s.second = turns;
            return;
        }
    }
    size_t i = 0;
    while (i < sts.size() && sts[i].first < status) i++;
