std::vector<Event> Tracker::next_turn() {
    std::vector<Event> ev;
    if (list_.empty()) return ev;
    long next;
    if (pos_ < 0) {
        round_ = 1;
        next = 0;
        ev.push_back(Event{Event::RoundStart, "", "", round_});
    } else {
        if (!vacant_) {
            Combatant &cur = list_[static_cast<size_t>(pos_)];
